  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']

    # Build lookup for distances
    dist_map = {}
    for a, b, d in dists:
        if a < b:
            key = (a, b)
        else:
            key = (b, a)
        dist_map[key] = d

    # Build edge list with mutual reachability
    edges = []
    for i in range(len(nodes)):
        for j in range(i+1, len(nodes)):
            a = nodes[i]
            b = nodes[j]
            if (a, b) not in dist_map:
                raise ValueError(f"Missing distance between {a} and {b}")
            d = dist_map[(a, b)]
            w = max(core[a], core[b], d)
            edges.append((w, a, b))

    # Sort deterministically: weight ascending, then first endpoint, then second
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find (Disjoint Set Union)
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Graph is disconnected")

    return {
        "edges": mst_edges,
        "total_weight": total_weight
    }
